SELECT ORDER_NO, SCHEDULE_DATE, LINING_CODE AS PADDING_CODE, NIGHT_FINISH_QTY, DAY_FINISH_QTY, MID_FINISH_QTY, FACTORY_CODE FROM MES_PAD_DAY_FINISH_QTY WHERE DATA_VERSION = #{dataVersion}
AND FACTORY_CODE = #{factoryCode}
AND COMPANY_CODE = #{companyCode}

SELECT SCHEDULE_DATE,
       LINING_CODE AS PADDING_CODE,
       FINISH_QTY,
       FACTORY_CODE
FROM MES_PAD_DAY_FINISH_TOTL
WHERE DATA_VERSION = #{dataVersion}

    AND FACTORY_CODE = #{factoryCode}


    AND COMPANY_CODE = #{companyCode}
